<script setup lang="ts">
import {ref,computed,watch,onMounted} from 'vue';
import Modal from '../components/Modal.vue';
import EmployeeEdit from '../components/EmployeeEdit.vue';
import {api} from '../api';import {useWorkspace,useSession,type WorkTab} from '../stores';
const props=defineProps<{tab:WorkTab;embedded?:boolean}>(),work=useWorkspace(),session=useSession();
const data=ref<any>(null),error=ref(''),loading=ref(false),search=ref(''),status=ref('all'),position=ref(''),page=ref(1),movement=ref('all');
const exporting=ref(false),historyTab=ref<WorkTab|null>(null),editing=ref<any>(null),message=ref('');
async function saved(){editing.value=null;message.value='員工資料已儲存';await load();}
const counts=computed(()=>{const employees=data.value?.employees||[];return {total:employees.length,active:employees.filter((e:any)=>e.is_active===true).length,resigned:employees.filter((e:any)=>e.is_active===false).length};});
const historyMode=props.tab.kind==='employee-history';
const statusLabel=(s:string)=>({active:'在職',resigned:'離職',full_month:'整月在職',new_hire:'新進',leave_of_absence:'留職停薪',leave_without_pay:'留職停薪',transferred_in:'調入',transferred_out:'調出',promoted:'升職',support_rotation:'支援卡班',dual_store_manager:'擔任雙店長',leave_return:'留停復職'}[s]||s);
const typeLabel=(s:string)=>({promotion:'升遷',onboarding:'到職',resignation:'離職',transfer:'調店',reinstatement:'復職',acting_manager:'代理店長',store_transfer:'調店',leave_without_pay:'留職停薪',return_to_work:'復職',pass_probation:'通過試用'}[s]||s);
const positions=computed(()=>Array.from(new Set<string>((data.value?.employees||[]).map((e:any)=>e.current_position).filter(Boolean))).sort());
const rows=computed(()=>(data.value?.employees||[]).filter((e:any)=>(status.value==='all'||e.is_active===(status.value==='active'))&&(!position.value||e.current_position===position.value)&&[e.employee_code,e.employee_name,e.current_position].join(' ').toLowerCase().includes(search.value.trim().toLowerCase())));
const history=computed(()=>(data.value?.history||[]).filter((h:any)=>movement.value==='all'||h.movement_type===movement.value));
const pages=computed(()=>Math.max(1,Math.ceil((historyMode?history.value.length:rows.value.length)/100))),visible=computed(()=>(historyMode?history.value:rows.value).slice((page.value-1)*100,page.value*100));
watch([search,status,position,movement],()=>page.value=1);
async function load(){loading.value=true;error.value='';data.value=null;try{data.value=await api(historyMode?'employees?history='+encodeURIComponent(props.tab.recordId||''):'employees');page.value=Math.min(page.value,pages.value);}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
function openHistory(e:any){historyTab.value={...props.tab,kind:'employee-history',recordId:e.employee_code,payload:{name:e.employee_name}};}
async function download(){if(exporting.value||!rows.value.length||loading.value)return;exporting.value=true;error.value='';
 const snapshot=rows.value.map((e:any)=>({...e,status_label:statusLabel(e.current_status)||(e.is_active?'在職':'離職')}));
 try{const {employeeWorkbook}=await import('../employee-export');const url=URL.createObjectURL(new Blob([employeeWorkbook(snapshot)],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));const a=document.createElement('a');a.href=url;a.download='員工篩選結果_'+new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{error.value='Excel 匯出失敗，請重試。';}finally{exporting.value=false;}}
onMounted(load);
</script>
<template>
<header class="page-heading"><div><p v-if="!embedded" class="eyebrow">組織與門市 / 員工管理</p><h1 v-if="!embedded">{{historyMode?'員工異動歷程':'員工管理'}}</h1><p v-if="historyMode">{{tab.recordId}} · {{tab.payload?.name}}</p></div><div class="actions"><button :disabled="loading" @click="load">重新整理</button><button v-if="!historyMode&&data?.capabilities.create" class="primary" @click="work.open('employee-create')">新增員工</button><button v-if="!historyMode&&session.data?.capabilities.employeeBirthdays" @click="work.open('employee-birthdays')">生日匯入</button></div></header>
<p v-if="message" class="notice" role="status">{{message}}</p><p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="loading" role="status">載入員工資料…</p>
<template v-else-if="data">
<template v-if="!historyMode"><section aria-label="員工人數統計" class="employee-dashboard"><dl><div><dt>總員工數</dt><dd>{{counts.total.toLocaleString('zh-TW')}}<small>人</small></dd></div><div><dt>在職員工數</dt><dd>{{counts.active.toLocaleString('zh-TW')}}<small>人</small></dd></div><div><dt>離職員工數</dt><dd>{{counts.resigned.toLocaleString('zh-TW')}}<small>人</small></dd></div></dl><p>依完整可見名冊統計，同一員編計算一次；不受下方篩選影響。</p></section><div class="filters"><label>搜尋員工<input v-model="search" placeholder="員編、姓名或職位"></label><label>在職狀態<select v-model="status" aria-label="在職狀態"><option value="all">全部</option><option value="active">在職</option><option value="resigned">離職</option></select></label><label>職位<select v-model="position" aria-label="職位"><option value="">全部職位</option><option v-for="p in positions" :key="p">{{p}}</option></select></label></div><div class="export-row"><p>符合 {{rows.length}} / {{data.total}} 位員工</p><button :disabled="exporting||!rows.length" @click="download">{{exporting?'正在匯出…':'匯出篩選結果 Excel'}}</button></div>
<div class="module-table"><table><thead><tr><th>員編</th><th>姓名</th><th>當前職位</th><th>階段</th><th>狀態</th><th>到職日</th><th>生日</th><th>操作</th></tr></thead><tbody><tr v-for="e in visible" :key="e.employee_code"><td>{{e.employee_code}}</td><td>{{e.employee_name}}</td><td>{{e.current_position||'未提供'}}</td><td data-testid="employee-stage">{{e.newbie_level||'—'}}</td><td>{{statusLabel(e.current_status)||(e.is_active?'在職':'離職')}}</td><td>{{e.start_date||'—'}}</td><td>{{e.birthday||'—'}}</td><td><div class="actions"><button v-if="data.capabilities.edit" @click="editing=e">編輯</button><button @click="openHistory(e)">異動歷程</button></div></td></tr><tr v-if="!rows.length"><td colspan="8">沒有符合條件的員工。</td></tr></tbody></table></div></template>
<template v-else><label class="history-filter">紀錄類型<select v-model="movement" aria-label="紀錄類型"><option value="all">全部異動</option><option value="promotion">升遷</option><option v-for="t in [...new Set<string>(data.history.map((r:any)=>r.movement_type))].filter(t=>t!=='promotion')" :key="t" :value="t">{{typeLabel(t)}}</option></select></label><p>{{history.length}} 筆紀錄</p><ol class="history"><li v-for="h in visible" :key="h.id"><div class="history-heading"><time>{{h.movement_date}}</time><strong>{{typeLabel(h.movement_type)}}</strong><span>{{h.store?.store_code}} {{h.store?.store_name||'未指定門市'}}</span></div><p>{{h.old_label}} → <strong>{{h.new_label}}</strong></p><p v-if="h.display_notes" class="notes">{{h.display_notes}}</p></li></ol><p v-if="!history.length">沒有可查看的異動紀錄。</p></template>
<div class="pagination"><span>第 {{page}} / {{pages}} 頁</span><button :disabled="page===1" @click="page--">上一頁</button><button :disabled="page===pages" @click="page++">下一頁</button></div></template>
<Modal v-if="historyTab" title="員工異動歷程" wide @cancel="historyTab=null"><Employees :tab="historyTab" embedded /><div class="dialog-actions"><button @click="historyTab=null">關閉</button></div></Modal>
<EmployeeEdit v-if="editing" :employee="editing" :tab="tab" @close="editing=null" @saved="saved" />
</template>
<style scoped>.employee-dashboard{margin-top:24px;padding:20px 0 12px;border-block:1px solid var(--line)}.employee-dashboard dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin:0}.employee-dashboard dl>div{padding:0 24px;border-left:1px solid var(--line)}.employee-dashboard dl>div:first-child{padding-left:0;border-left:0}.employee-dashboard dt{font-size:14px;color:var(--muted)}.employee-dashboard dd{margin:8px 0 0;font-size:30px;font-weight:600;font-variant-numeric:tabular-nums}.employee-dashboard small{font-size:13px;font-weight:400;margin-left:8px;color:var(--muted)}.employee-dashboard p{margin:16px 0 0;font-size:12px;color:var(--muted)}@media(max-width:600px){.employee-dashboard dl{grid-template-columns:1fr;gap:12px}.employee-dashboard dl>div,.employee-dashboard dl>div:first-child{padding:0;display:flex;align-items:center;justify-content:space-between;border:0}.employee-dashboard dd{margin:0;font-size:26px}}.export-row{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:12px}.actions,.filters,.history-heading{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.filters{margin:24px 0;align-items:end}label{display:grid;gap:8px}.filters input{width:280px;max-width:100%}.history-filter{max-width:240px}.history{padding:0;list-style:none;max-width:1000px}.history li{padding:20px 0;border-top:1px solid var(--line)}time,.history-heading span{color:var(--muted)}.notes{white-space:pre-wrap;overflow-wrap:anywhere}.pagination{display:flex;gap:12px;align-items:center;justify-content:flex-end;margin-top:20px}.pagination span{margin-right:auto}.module-table td{overflow-wrap:anywhere}@media(max-width:600px){.filters{display:grid}.filters input,.filters select{width:100%}.module-table table{min-width:840px}}</style>
